mapper.update:
UPDATE location_points
SET journey_id = #{journeyId}
WHERE user_id = #{userId} AND session_id = #{sessionId} AND journey_id IS NULL

mapper.select:
SELECT id, user_id AS userId, journey_id AS journeyId, session_id AS sessionId, lat, lon,
       accuracy_m AS accuracyM, speed_mps AS speedMps, heading_deg AS headingDeg, recorded_at AS recordedAt
FROM location_points
WHERE user_id = #{userId} AND journey_id = #{journeyId}
ORDER BY recorded_at, id
LIMIT #{limit}
